//! Ogg page framing and packet reconstruction with CRC verification.
use sse_core::{Error,Result};
#[derive(Clone,Debug)]pub struct Packet{pub data:Vec<u8>,pub granule:Option<u64>,pub bos:bool,pub eos:bool}
fn crc(data:&[u8])->u32{let mut c=0u32;for b in data{c^=u32::from(*b)<<24;for _ in 0..8{c=if c&0x8000_0000!=0{(c<<1)^0x04c11db7}else{c<<1};}}c}
fn le32(b:&[u8])->Result<u32>{Ok(u32::from_le_bytes(<[u8;4]>::try_from(b).map_err(|_|Error::damaged("short Ogg u32"))?))}fn le64(b:&[u8])->Result<u64>{Ok(u64::from_le_bytes(<[u8;8]>::try_from(b).map_err(|_|Error::damaged("short Ogg u64"))?))}
pub fn packets(input:&[u8])->Result<Vec<Packet>>{let mut p=0usize;let mut serial=None;let mut seq=0u32;let mut pending=Vec::new();let mut out=Vec::new();while p<input.len(){let head=input.get(p..p.saturating_add(27)).ok_or_else(||Error::damaged("truncated Ogg page"))?;if head.get(0..4)!=Some(b"OggS")||head.get(4)!=Some(&0){return Err(Error::damaged("invalid Ogg capture/version"));}let flags=*head.get(5).ok_or_else(||Error::damaged("Ogg flags"))?;let granule=le64(head.get(6..14).ok_or_else(||Error::damaged("Ogg granule"))?)?;let s=le32(head.get(14..18).ok_or_else(||Error::damaged("Ogg serial"))?)?;let q=le32(head.get(18..22).ok_or_else(||Error::damaged("Ogg sequence"))?)?;let expected=le32(head.get(22..26).ok_or_else(||Error::damaged("Ogg CRC"))?)?;if let Some(x)=serial{if x!=s{return Err(Error::Refused("chained Ogg streams are unsupported".to_owned()));}}else{serial=Some(s);}if q!=seq{return Err(Error::damaged("Ogg page sequence gap"));}seq=seq.saturating_add(1);let n=usize::from(*head.get(26).ok_or_else(||Error::damaged("Ogg segment count"))?);let lace=input.get(p+27..p+27+n).ok_or_else(||Error::damaged("truncated Ogg lacing"))?;let body_len=lace.iter().fold(0usize,|a,x|a.saturating_add(usize::from(*x)));let end=p.checked_add(27+n+body_len).ok_or_else(||Error::damaged("Ogg page size overflow"))?;let page=input.get(p..end).ok_or_else(||Error::damaged("truncated Ogg body"))?;let mut check=page.to_vec();if let Some(x)=check.get_mut(22..26){x.fill(0);}if crc(&check)!=expected{return Err(Error::damaged("Ogg CRC mismatch"));}if flags&1==0&&!pending.is_empty(){return Err(Error::damaged("Ogg continuation flag missing"));}if flags&1!=0&&pending.is_empty(){return Err(Error::damaged("unexpected Ogg continuation"));}let mut bp=p+27+n;for (i,l) in lace.iter().enumerate(){let z=usize::from(*l);let part=input.get(bp..bp+z).ok_or_else(||Error::damaged("Ogg segment"))?;pending.extend_from_slice(part);bp=bp.saturating_add(z);if z<255{let last=i+1==n;out.push(Packet{data:std::mem::take(&mut pending),granule:(last&&granule!=u64::MAX).then_some(granule),bos:flags&2!=0&&out.is_empty(),eos:flags&4!=0&&last});}}p=end;}if !pending.is_empty(){return Err(Error::damaged("truncated Ogg packet"));}Ok(out)}
#[cfg(test)]mod tests{use super::*;#[test]fn crc_vector(){assert_eq!(crc(b""),0);}}